import React from "react";
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faBriefcase } from '@fortawesome/free-solid-svg-icons';
import { VerticalTimeline, VerticalTimelineElement }  from 'react-vertical-timeline-component';
import 'react-vertical-timeline-component/style.min.css';
import '../assets/styles/Timeline.scss'
import { timelineElements } from "../constants/cons";

interface TimelineElementProps {
  date: string;
  title: string;
  location: string;
  description: string;
}

const TimelineElement: React.FC<TimelineElementProps> = ({ date, title, location, description }) => (
  <VerticalTimelineElement
    className="vertical-timeline-element--work"
    date={date}
    iconStyle={{ background: 'var(--timeline-icon-bg)', color: '#fff' }}
    icon={<FontAwesomeIcon icon={faBriefcase} />}
  >
    <h3 className="vertical-timeline-element-title">{title}</h3>
    <h4 className="vertical-timeline-element-subtitle">{location}</h4>
    <p>{description}</p>
  </VerticalTimelineElement>
);

function Timeline() {
  return (
    <section id="history" aria-labelledby="history-heading">
      <div className="items-container">
        <h1 id="history-heading">Career History</h1>
        <VerticalTimeline>
          {timelineElements.map((element, index) => (
            <TimelineElement
              key={index}
              date={element.date}
              title={element.title}
              location={element.location}
              description={element.description}
            />
          ))}
        </VerticalTimeline>
      </div>
    </section>
  );
}

export default Timeline;